# deb dependencies of the legacy hikarisub package (packaging/linux/resolve-deps.sh).
# One line per host soname the app tree needs: "<soname> <dependency>". The
# alternatives cover the 64-bit time_t renames of Ubuntu 24.04 and later
# (libglib2.0-0t64 and so on). The package build fails on a soname that has
# no line here.
ld-linux-x86-64.so.2      @glibc
libc.so.6                 @glibc
libm.so.6                 @glibc
libdl.so.2                @glibc
libpthread.so.0           @glibc
librt.so.1                @glibc
libresolv.so.2            @glibc
libstdc++.so.6            libstdc++6 (>= 12)
libgcc_s.so.1             libgcc-s1
libgtk-3.so.0             libgtk-3-0t64 | libgtk-3-0
libgdk-3.so.0             libgtk-3-0t64 | libgtk-3-0
libgdk_pixbuf-2.0.so.0    libgdk-pixbuf-2.0-0
libpango-1.0.so.0         libpango-1.0-0
libpangocairo-1.0.so.0    libpangocairo-1.0-0
libpangoft2-1.0.so.0      libpangoft2-1.0-0
libcairo.so.2             libcairo2
libcairo-gobject.so.2     libcairo-gobject2
libatk-1.0.so.0           libatk1.0-0t64 | libatk1.0-0
libharfbuzz.so.0          libharfbuzz0b
libglib-2.0.so.0          libglib2.0-0t64 | libglib2.0-0
libgobject-2.0.so.0       libglib2.0-0t64 | libglib2.0-0
libgio-2.0.so.0           libglib2.0-0t64 | libglib2.0-0
libgmodule-2.0.so.0       libglib2.0-0t64 | libglib2.0-0
libgthread-2.0.so.0       libglib2.0-0t64 | libglib2.0-0
libgstreamer-1.0.so.0     libgstreamer1.0-0
libgstbase-1.0.so.0       libgstreamer1.0-0
libgstapp-1.0.so.0        libgstreamer-plugins-base1.0-0
libgstaudio-1.0.so.0      libgstreamer-plugins-base1.0-0
libgstvideo-1.0.so.0      libgstreamer-plugins-base1.0-0
libX11.so.6               libx11-6
libXext.so.6              libxext6
libXtst.so.6              libxtst6
libXxf86vm.so.1           libxxf86vm1
libSM.so.6                libsm6
libICE.so.6               libice6
libxkbcommon.so.0         libxkbcommon0
libwayland-client.so.0    libwayland-client0
libwayland-egl.so.1       libwayland-egl1
libGL.so.1                libgl1
libEGL.so.1               libegl1
libGLU.so.1               libglu1-mesa
libfontconfig.so.1        libfontconfig1
libfreetype.so.6          libfreetype6
libfribidi.so.0           libfribidi0
libbrotlidec.so.1         libbrotli1
libffi.so.8               libffi8
libz.so.1                 zlib1g
libzstd.so.1              libzstd1
libexpat.so.1             libexpat1
libdbus-1.so.3            libdbus-1-3
libsystemd.so.0           libsystemd0
libasound.so.2            libasound2t64 | libasound2
libpulse.so.0             libpulse0
# runtime
# The GStreamer plugins legacy plays through, an audio sink, the gio tool
# for move-to-trash, the icon theme, curl and the CA certificates the
# update helper checks a release's SHA256SUMS with, and (recommended) the
# updater's password prompt and an English dictionary.
depends     gstreamer1.0-plugins-base
depends     gstreamer1.0-plugins-good
depends     gstreamer1.0-libav
depends     gstreamer1.0-pulseaudio | gstreamer1.0-pipewire | gstreamer1.0-alsa
depends     libglib2.0-bin
depends     hicolor-icon-theme
depends     curl
depends     ca-certificates
recommends  gstreamer1.0-plugins-bad
recommends  hunspell-en-us
recommends  pkexec | policykit-1
